import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
// PrismaClient is generated by `prisma generate` from packages/db/prisma/schema.prisma
// into packages/db/generated/client, and re-exported via @workspace/db's `main`.
import { PrismaClient } from '@workspace/db';

/**
 * Thin wrapper around the generated PrismaClient that hooks into Nest's
 * lifecycle so the connection pool opens/closes with the application.
 */
@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(PrismaService.name);

  constructor() {
    super({
      log: [
        { emit: 'event', level: 'warn' },
        { emit: 'event', level: 'error' },
      ],
    });
  }

  async onModuleInit(): Promise<void> {
    await this.$connect();
    this.logger.log('Connected to Postgres via Prisma');
  }

  async onModuleDestroy(): Promise<void> {
    await this.$disconnect();
  }

  /**
   * Best-effort connectivity check used by the /health endpoint. Never
   * throws - callers should treat a `false` return as "degraded", not fatal.
   */
  async isHealthy(): Promise<boolean> {
    try {
      await this.$queryRaw`SELECT 1`;
      return true;
    } catch {
      return false;
    }
  }
}
